using System.Text.Json.Nodes;
using Modeller.Application;
using Modeller.Core;
static class BindingPlanTests
{
    public static async Task Run(string root,Action<bool,string> check){
        var repository=new SnapshotRepository(Path.Combine(root,"binding-plans"));repository.Create("synthetic","Synthetic","");using var remote=new RemoteDefinitions();var actor=new ModellingIdentity("synthetic","shared",true,[],false,["modeller"]);var workspace=new TerminologyWorkspace(repository,actor,remote);
        async Task<JsonObject> Call(string tool,JsonObject args)=>(JsonObject)await workspace.Execute(tool,args,CancellationToken.None);
        async Task Reject(string tool,JsonObject args,string code){try{await Call(tool,args);throw new Exception("Expected "+code);}catch(ProcessingException error){check(error.Code==code,code);}}
        const string system="https://example.org/codes";const string model="<template xmlns=\"openEHR/v1/Template\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"><definition archetype_id=\"openEHR-EHR-OBSERVATION.synthetic.v1\"><Rule path=\"/data/items[at0001]\"><constraint xsi:type=\"textConstraint\"><includedValues>https://example.org/codes::A</includedValues><excludedValues>https://example.org/codes::B</excludedValues></constraint></Rule></definition></template>";
        var source=repository.Save("synthetic","templates/model.oet",model,new JsonObject(),null);JsonObject Args()=>new(){["project"]="synthetic",["path"]="templates/model.oet"};
        var inspection=await Call("model_terminology_inspect",Args());check(inspection["inspection"]?["slots"]?.AsArray().Count==1&&inspection["inspection"]?["slots"]?[0]?["excluded_values"]?[0]?.GetValue<string>()==system+"::B","inspection preserves explicit exclusions and source codings");
        JsonObject Set(string canonical,string version)=>new(){["kind"]="value_set",["canonical"]=canonical,["version"]=version,["name"]="Synthetic set",["provenance"]=new JsonObject{["source"]="Synthetic fixture"},["concepts"]=new JsonArray(new JsonObject{["system"]=system,["version"]="1",["code"]="A",["display"]="Synthetic A"})};
        await Call("terminology_catalogue_save",new JsonObject{["project"]="synthetic",["record"]=Set("https://example.org/set","1")});var plan=await Call("terminology_binding_plan",Args());check(plan["analysis"]?["decisions"]?[0]?["candidates"]?.AsArray().Count==1&&plan["analysis"]?["decisions"]?[0]?["candidates"]?[0]?["code_system_versions_confirmed"]?.GetValue<bool>()==false,"membership candidate does not invent a code-system version");
        var coding=new JsonObject{["kind"]="code_system",["canonical"]=system,["version"]="1",["name"]="Synthetic codes",["provenance"]=new JsonObject{["source"]="Synthetic fixture"},["concepts"]=new JsonArray(new JsonObject{["code"]="A",["display"]="Synthetic A"})};await Call("terminology_catalogue_save",new JsonObject{["project"]="synthetic",["record"]=coding});
        var save=Args();save["modelRevision"]=source["revision"]!.DeepClone();save["aliases"]=new JsonArray(new JsonObject{["terminology_id"]=system,["system"]=system,["version"]="1"});var saved=await Call("terminology_binding_plan_save",save);check(saved["plan"]?["analysis"]?["decisions"]?[0]?["code_validation"]?[0]?["valid"]?.GetValue<bool>()==true&&repository.Artifact("synthetic","templates/model.oet")["sha256"]?.GetValue<string>()==source["sha256"]?.GetValue<string>(),"pinned CodeSystem validation leaves original model unchanged");
        var current=await Call("terminology_binding_plan_get",Args());check(current["freshness"]?["status"]?.GetValue<string>()=="CURRENT"&&current["release_ready"]?.GetValue<bool>()==false,"saved current analysis is neither approval nor release evidence");
        await Call("terminology_catalogue_save",new JsonObject{["project"]="synthetic",["record"]=Set("https://example.org/set","2")});var changed=await Call("terminology_binding_plan_get",Args());check(changed["freshness"]?["status"]?.GetValue<string>()=="STALE_OR_MODIFIED"&&changed["freshness"]?["catalogue_matches"]?.GetValue<bool>()==false,"new catalogue edition invalidates saved analysis");
        var ambiguous=await Call("terminology_binding_plan",Args());check(ambiguous["analysis"]?["decisions"]?[0]?["candidates"]?.AsArray().Count==2&&ambiguous["analysis"]?["findings"]?.AsArray().OfType<JsonObject>().Any(f=>f["code"]?.GetValue<string>()=="AMBIGUOUS_VALUE_SET_CANDIDATES")==true,"multiple editions remain ambiguous candidates");
        var invalidAlias=Args();invalidAlias["aliases"]=new JsonArray(new JsonObject{["terminology_id"]=system,["system"]="https://example.org/other"});await Reject("terminology_binding_plan",invalidAlias,"CANONICAL_ALIAS_CANNOT_REMAP_SYSTEM");
        invalidAlias["aliases"]=new JsonArray(new JsonObject{["terminology_id"]="local",["system"]=system});await Reject("terminology_binding_plan",invalidAlias,"LOCAL_TERMINOLOGY_ALIAS_REQUIRES_ARCHETYPE");
        var query=model.Replace("<includedValues>https://example.org/codes::A</includedValues>","<termQueryId terminologyID=\"SNOMED-CT\" queryName=\"selected-query\"/>",StringComparison.Ordinal);repository.Save("synthetic","templates/query.oet",query,new JsonObject(),null);var queryPlan=await Call("terminology_binding_plan",new JsonObject{["project"]="synthetic",["path"]="templates/query.oet"});check(queryPlan["analysis"]?["decisions"]?[0]?["action"]?.GetValue<string>()=="PRESERVE_EXISTING"&&queryPlan["analysis"]?["decisions"]?[0]?["existing_references"]?[0]?["canonical"] is null,"named query is preserved without inventing a FHIR canonical");
        var bad=Set("https://example.org/invalid","1");bad["concepts"]!.AsArray().Add("invalid-row");await Reject("terminology_catalogue_save",new JsonObject{["project"]="synthetic",["record"]=bad},"INVALID_TERMINOLOGY_LIST");
        var malformedConditions=new JsonObject{["kind"]="concept_map",["canonical"]="https://example.org/map",["version"]="1",["name"]="Synthetic",["provenance"]=new JsonObject{["source"]="Synthetic fixture"},["mappings"]=new JsonArray(new JsonObject{["source"]=new JsonObject{["system"]=system,["code"]="A"},["target"]=new JsonObject{["system"]=system,["code"]="B"},["relationship"]="equivalent",["conditions"]=new JsonObject()})};await Reject("terminology_catalogue_save",new JsonObject{["project"]="synthetic",["record"]=malformedConditions},"INVALID_TERMINOLOGY_LIST");
    }
}
